def number_existing_answers(apps, schema_editor):
    """
    Lembar lama diurutkan lewat join ke exam_questions tanpa filter paket, sehingga soal yang
    dipakai di beberapa paket muncul ganda. Nomor urut kini disimpan per lembar, mengikuti
    urutan soal di paket milik sesi itu. Opsi lama tetap tampil A-E apa adanya.
    """
    ExamSession = apps.get_model('exam_engine', 'ExamSession')
    StudentAnswer = apps.get_model('exam_engine', 'StudentAnswer')
    ExamQuestion = apps.get_model('schedules', 'ExamQuestion')

    order_cache = {}
    to_update = []
    for session in ExamSession.objects.select_related('schedule').iterator():
        exam_id = session.schedule.exam_id
        if exam_id not in order_cache:
            order_cache[exam_id] = dict(
                ExamQuestion.objects.filter(exam_id=exam_id).values_list('question_id', 'order_number')
            )
        exam_order = order_cache[exam_id]
        answers = list(StudentAnswer.objects.filter(session_id=session.id))
        answers.sort(key=lambda a: (exam_order.get(a.question_id, 10 ** 6), str(a.id)))
        for position, ans in enumerate(answers, start=1):
            ans.order_number = position
            to_update.append(ans)
        if len(to_update) >= 2000:
            StudentAnswer.objects.bulk_update(to_update, ['order_number'])
            to_update = []
    if to_update:
        StudentAnswer.objects.bulk_update(to_update, ['order_number'])


